def transform(input, state=None):
    # AI : prefer html snapshots; Ray is optional for live URL fan-out.
    import re

    def to_py(v):
        return v.to_py() if hasattr(v, "to_py") else v

    def strip_html(html):
        text = re.sub(r"(?is)<script[^>]*>.*?</script>", " ", html or "")
        text = re.sub(r"(?is)<style[^>]*>.*?</style>", " ", text)
        text = re.sub(r"(?s)<[^>]+>", " ", text)
        return re.sub(r"\s+", " ", text).strip()

    def fetch_url(url):
        if not url:
            return ""
        try:
            import urllib.request
            req = urllib.request.Request(url, headers={"User-Agent": "SpineResearchBot/1.0"})
            with urllib.request.urlopen(req, timeout=12) as resp:
                return resp.read().decode("utf-8", "replace")
        except Exception:
            return ""

    def scrape_one(row):
        row = to_py(row) or {}
        url = str(row.get("url") or "")
        title = str(row.get("title") or "")
        html = str(row.get("html") or "")
        fetched = False
        if not str(html).strip() and url:
            html = fetch_url(url)
            fetched = bool(html)
        text = strip_html(html)
        if not text:
            text = str(row.get("snippet") or "").strip()
        status = "fetched" if fetched and text else ("ok" if text else "empty")
        return {"url": url, "title": title, "text": text[:12000], "status": status}

    raw = to_py(input)
    rows = raw if isinstance(raw, list) else list((raw or {}).get("results") or [])
    try:
        import ray
        if not ray.is_initialized():
            ray.init(ignore_reinit_error=True, include_dashboard=False)
        remote_fn = ray.remote(scrape_one)
        return ray.get([remote_fn.remote(r) for r in rows])
    except Exception:
        return [scrape_one(r) for r in rows]

